      第三者: "防因口舌而推远配偶——忍一句则安。家丑不外扬，内部解决。",
      婚期: "宜选壬癸日（水旺日）。水主柔，以柔克刚。",
      相处建议: "只论情、不论理。赢了架势输了人心不值。退一步海阔天空。",
      人际关系: "人际关系以和为贵——忍一时风平浪静。好斗者人缘差，退让者人缘好。"
