      项目回款: "回款顺利——大有则资金畅达。见旺先收一半，不可贪。",
      出行: "出行吉利——大有则处处逢源。南方宜开阔明亮，忌遮挡。",
      流年: "此年丰盛显达——宜顺天休命。夏季火旺时运势最旺。盛中须防骄。",
      择日: "宜选丙丁日（火旺日）或庚辛日（金旺日）。火克金则财在光明中得。",
      贵人小人: "贵人在权势之人中——大有则贵人多。小人藏于嫉妒者中——盛极易招忌。",
      决策选择: "决策宜顺天休命——盛时守谦履信。广施则福长，见旺先收一半。"
